# get point pattern using per-core 
# convex hull as window of observation
xy &lt;- grep("global_mm", names(cd &lt;- colData(sce)))
cs &lt;- split(colnames(sce), sce$sid)
pp &lt;- lapply(cs, \(.) {
    ow &lt;- ripras(xy &lt;- as.matrix(cd[., xy]))
    xy &lt;- xy[which(cd$lv1[.] == "tum"), ]
    pp &lt;- ppp(xy[,1], xy[,2], window=ow)
})
# visualize kernel density estimate
# of tumoral density across cores
kd &lt;- lapply(pp, density.ppp)
par(mfrow=c(4, 5), mar=c(1,0,0,0))
for (. in names(kd)) plot(kd[[.]], main=., col=pals::jet())












df &lt;- data.frame(colData(sce))
xs &lt;- seq(min(ds &lt;- .q(df$nns.tum)), max(ds), l=21)
sce$bin &lt;- df$bin &lt;- cut(ds, breaks=xs, include.lowest=TRUE)
hist(ds, breaks=xs, xlab="q-scaled tumoral neighbors", ylab="# cells", main="")









fd &lt;- df |&gt;
    group_by(bin) |&gt;
    summarise(across(starts_with("fqs."), mean)) |&gt;
    pivot_longer(starts_with("fqs.")) |&gt;
    group_by(name) |&gt; mutate_at("value", .z)
yo &lt;- fd |&gt; 
    ungroup() |&gt;
    arrange(value) |&gt;
    distinct(name) |&gt;
    pull(name) |&gt; rev()
#yo &lt;- names(sort(apply(pivot_wider(fd)[, -1], 2, which.max)))
ggplot(fd, aes(bin, name, fill=value)) + geom_tile() + 
    scale_fill_gradientn(colors=rev(hcl.colors(9, "RdBu"))) +
    scale_y_discrete(limits=yo)
